mod solution;

fn main() {
    let cases = [
    (r#"[1,3,5,7,9,12,15,18,21,24]"#, r#"8"#),
    (r#"[21,30]"#, r#"0"#),
    (r#"
[21,30]
"#, r#"0"#),
    (r#"  
[1,3,5,7,9,12,15,18,21,24]
  "#, r#"8"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS exponential-search");
}
